public static Career Create(int choice,string name,uint seed){var s=new Career{Seed=seed,Player=choice<0?11:choice,Cash=choice<0?85:135};for(int i=0;i<11;i++){var t=new Team{Id=i,Name=teamNames[i],Color=colors[i],Engine=providers[i],Works=new[]{1,2,3,4,9}.Contains(i)};for(int j=0;j<6;j++)t.Base[j]=ratings[i]+(j%3-1)*2;for(int j=0;j<6;j++)t.Facilities[j].Level=1;int ep=Array.IndexOf(Engines,t.Engine);t.EngineRating=EnginePower[ep];t.EngineReliability=EngineReliability[ep];Powertrain.Reset(t);s.Teams.Add(t);
for(int j=0;j<2;j++){int id=i*2+j;var p=new Person{Id=id,Kind=0,Name=drivers[i][j],Age=ages[id],Rating=dr[id],Wins=wins[id],Titles=titles[id],Source="https://www.formula1.com/en/teams",RealRole="F1 driver"};p.Deal=new Contract{Team=i,Seat=j,Until=2026+id%3,Salary=Engine.Market(p),Role=j==0?"Первый пилот":"Равный статус"};s.People.Add(p);}
for(int j=0;j<6;j++){int kind=j<4?j+1:5,seat=j<4?0:j-4;var p=new Person{Id=100+i*6+j,Kind=kind,Name=staff[i][j],Age=40+j*3,Rating=Math.Min(98,ratings[i]+(j%3-1)*2),Source=staffSources[i],RealRole=j==0?"Team leadership":j==1?"Sporting / race operations":j==2?"Aerodynamics leadership":j==3?"Technical leadership":"Race engineering"};p.Deal=new Contract{Team=i,Seat=seat,Until=2026+(i+j)%3,Salary=Engine.Market(p),Role=Roles[kind]};s.People.Add(p);}
}
string[] free={"Yuki Tsunoda","Jack Doohan","Felipe Drugovich","Paul Aron"};for(int i=0;i<4;i++)s.People.Add(new Person{Id=22+i,Name=free[i],Kind=0,Age=23+i,Rating=82-i,Source="https://www.formula1.com/en/drivers",RealRole="Reserve / development driver"});
for(int kind=1;kind<=5;kind++)for(int j=0;j<3;j++)s.People.Add(new Person{Id=700+kind*10+j,Name=new[]{"Александр Вольф","Лука Моретти","Эмиль Ларсен"}[j]+" / "+Roles[kind],Age=35+j*5,Rating=70+j*3,Kind=kind,Fictional=true,RealRole="Вымышленный специалист"});
if(choice<0){var t=new Team{Id=11,Name=string.IsNullOrWhiteSpace(name)?"Apex Racing":name.Trim().Substring(0,Math.Min(35,name.Trim().Length)),Color="#ed252a",Engine="Ferrari",Base=new double[]{68,70,69,67,71,75},EngineRating=90,EngineReliability=90};Powertrain.Reset(t);s.Teams.Add(t);for(int j=0;j<2;j++)s.People.First(p=>p.Id==24+j).Deal=new Contract{Team=11,Seat=j,Until=2026,Salary=4,Role="Равный статус"};for(int kind=1;kind<=5;kind++)for(int j=0;j<(kind==5?2:1);j++){var p=s.People.First(x=>x.Kind==kind&&x.Deal==null);p.Deal=new Contract{Team=11,Seat=j,Until=2026,Salary=Engine.Market(p),Role=Roles[kind]};}}
foreach(var t in s.Teams)foreach(var d in Engine.Drivers(s,t.Id)){var re=Engine.Staff(s,t.Id,5,d.Deal.Seat);if(re!=null){t.Chemistry[d.Id.ToString()]=35;t.Pairs[d.Id.ToString()]=re.Id;}}
s.LastCarMetrics=CarModel.Values(Engine.Team(s,s.Player));Engine.Announce(s);Engine.Note(s,"Добро пожаловать в F1 Manager. Подготовьте детали, персонал и стратегии к сезону.");return s;}
